PC:
*{margin:0;padding:0;box-sizing:border-box}
:root{--brand:#123C32;--brand2:#1B5140;--accent:#B8893B;--accent2:#C09B4F;
--bg:#F5F4EF;--surf:#FFF;--surf2:#FAF9F4;--surf3:#F1EFE7;--line:#DDD9CB;--line2:#EAE7DC;
--ink:#16211C;--ink2:#4A544E;--muted:#7A8480;
--ok:#2E7D5B;--okbg:#DFEDE6;--warn:#C56A28;--warnbg:#F9E7D8;
--info:#3A5C8F;--infobg:#E5EBF5;--danger:#9C3B32;--dangerbg:#F7E2DF;
--dirty:#8A8F88;--dirtybg:#EDEBE3;--sh:0 1px 3px rgba(20,30,25,.06)}
.dark{--bg:#0D1512;--surf:#141F1B;--surf2:#18251F;--surf3:#1E2B25;--line:#283730;--line2:#22302A;
--ink:#E7ECE8;--ink2:#B2BEB8;--muted:#7C8A84;--okbg:#14372A;--warnbg:#3B2515;
--infobg:#18253C;--dangerbg:#381C19;--dirtybg:#212A25;--ok:#5BC192;--warn:#E29556;
--info:#7FA3DC;--danger:#D98B80;--dirty:#98A19A;--sh:0 1px 3px rgba(0,0,0,.3)}
body{font-family:"Hiragino Sans","Yu Gothic UI","Noto Sans JP",sans-serif;
background:#0A0E0C;color:#E7ECE8;line-height:1.6;font-size:14px}
.dc{position:sticky;top:0;z-index:200;background:#070B09;border-bottom:1px solid #1B2621;
padding:10px 20px;display:flex;gap:14px;align-items:center;flex-wrap:wrap}
.dc .lg{font-size:13.5px;font-weight:800}.dc .lg em{color:var(--accent2);font-style:normal}
.dc .bt{font-size:10.5px;color:#00A8A8;background:#0C231F;padding:3px 9px;border-radius:5px;font-weight:700}
.dc .grp{display:flex;gap:4px;background:#101714;padding:4px;border-radius:8px;flex-wrap:wrap}
.dc .gb{padding:6px 11px;border:none;border-radius:6px;background:transparent;color:#8A968F;
font-size:11px;cursor:pointer;font-family:inherit;font-weight:600;white-space:nowrap}
.dc .gb.on{background:var(--brand2);color:#fff}
.dc .gl{font-size:10px;color:#5B6862;align-self:center}
.dc .dm{margin-left:auto;padding:6px 12px;border-radius:7px;border:1px solid #283730;
background:#101714;color:#9AA7A0;font-size:11.5px;cursor:pointer;font-family:inherit}
.wrap{padding:22px 20px 40px;max-width:1560px;margin:0 auto}
.hd h1{font-size:19px;margin-bottom:5px}
.hd p{font-size:12.5px;color:#7C8A84;margin-bottom:18px;line-height:1.75;max-width:1080px}
.bf{border-radius:12px;overflow:hidden;box-shadow:0 18px 60px rgba(0,0,0,.55);
border:1px solid #202D27;background:var(--surf)}
.bb{background:#111917;padding:9px 14px;display:flex;align-items:center;gap:9px;border-bottom:1px solid #202D27}
.bb .dt{display:flex;gap:6px}
.bb .dt i{width:10px;height:10px;border-radius:50%;display:block}
.bb .dt i:nth-child(1){background:#E0645A}.bb .dt i:nth-child(2){background:#E3B34C}
.bb .dt i:nth-child(3){background:#57B77F}
.bb .url{flex:1;background:#0B120F;border-radius:6px;padding:5px 12px;font-size:11px;color:#7C8A84;
font-family:ui-monospace,monospace}
.app{display:flex;background:var(--bg);color:var(--ink);min-height:740px}
.sb{width:214px;flex-shrink:0;background:var(--brand);color:#fff;display:flex;flex-direction:column}
.sb .bd2{padding:16px 15px 13px;border-bottom:1px solid rgba(255,255,255,.11)}
.sb .bd2 .n1{font-size:14px;font-weight:800}.sb .bd2 .n1 em{color:var(--accent2);font-style:normal}
.sb .bd2 .n2{font-size:9.5px;color:#9FBFAF;margin-top:2px;letter-spacing:.04em}
.sb .pr{padding:12px 15px;border-bottom:1px solid rgba(255,255,255,.11);cursor:pointer}
.sb .pr .k{font-size:9px;color:#8FB3A2;font-weight:700;letter-spacing:.05em}
.sb .pr .v{font-size:12.5px;font-weight:700;margin-top:3px;display:flex;align-items:center;
justify-content:space-between;gap:6px}
.sb nav{padding:8px 0;flex:1;overflow-y:auto}.sb nav::-webkit-scrollbar{width:0}
.sb .sc2{font-size:9px;color:#7DA391;font-weight:700;padding:11px 15px 5px;letter-spacing:.06em}
.sb a{display:flex;align-items:center;gap:9px;padding:9px 15px;font-size:12.5px;
color:#C6D9CE;text-decoration:none;cursor:pointer;border-left:3px solid transparent}
.sb a:hover{background:rgba(255,255,255,.05)}
.sb a.on{background:rgba(255,255,255,.1);color:#fff;font-weight:700;border-left-color:var(--accent)}
.sb a .e{font-size:15px;width:18px;text-align:center}
.sb a .bg2{margin-left:auto;background:var(--accent);color:#241806;font-size:9.5px;font-weight:800;
padding:1px 6px;border-radius:9px}
.sb .ft2{padding:12px 15px;border-top:1px solid rgba(255,255,255,.11);font-size:10.5px;color:#8FB3A2}
.mn{flex:1;min-width:0;display:flex;flex-direction:column}
.tb2{background:var(--surf);border-bottom:1px solid var(--line);padding:13px 22px;
display:flex;align-items:center;gap:16px;flex-wrap:wrap}
.tb2 h2{font-size:16.5px;font-weight:800}
.tb2 .sub{font-size:11.5px;color:var(--muted);margin-top:1px}
.tb2 .rt{margin-left:auto;display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.ct2{padding:20px 22px 30px;overflow-y:auto;flex:1}
.btn{padding:8px 14px;border-radius:7px;border:1px solid var(--line);background:var(--surf);
color:var(--ink2);font-size:12px;font-family:inherit;cursor:pointer;font-weight:600;
display:inline-flex;align-items:center;gap:6px;white-space:nowrap}
.btn:hover{background:var(--surf3)}
.btn.p{background:var(--brand);color:#fff;border-color:var(--brand)}
.btn.p:hover{background:var(--brand2)}
.btn.sm{padding:5px 10px;font-size:11px}
.sel{padding:8px 11px;border-radius:7px;border:1px solid var(--line);background:var(--surf);
color:var(--ink);font-size:12px;font-family:inherit;cursor:pointer}
.card{background:var(--surf);border:1px solid var(--line);border-radius:11px;box-shadow:var(--sh)}
.card>h3{font-size:13px;font-weight:800;padding:14px 16px;border-bottom:1px solid var(--line2);
display:flex;align-items:center;gap:8px}
.card>h3 .rt2{margin-left:auto;font-size:11px;font-weight:600;color:var(--muted)}
.card .bdy{padding:16px}.card .bdy.np{padding:0}
.grid{display:grid;gap:14px}
.g2{grid-template-columns:1fr 1fr}.g3{grid-template-columns:repeat(3,1fr)}
.g4{grid-template-columns:repeat(4,1fr)}.g21{grid-template-columns:2fr 1fr}
.g12{grid-template-columns:1fr 2fr}.g31{grid-template-columns:3fr 1fr}
.kpi{background:var(--surf);border:1px solid var(--line);border-radius:11px;padding:15px 16px;box-shadow:var(--sh)}
.kpi .k{font-size:10.5px;color:var(--muted);font-weight:700;display:flex;align-items:center;gap:5px}
.kpi .v{font-size:29px;font-weight:800;line-height:1.15;margin-top:5px;font-variant-numeric:tabular-nums}
.kpi .v small{font-size:13px;font-weight:700;color:var(--muted)}
.kpi .d{font-size:10.5px;color:var(--muted);margin-top:4px}
.kpi.ok{border-left:3px solid var(--ok)}.kpi.wn{border-left:3px solid var(--warn)}
.kpi.dg{border-left:3px solid var(--danger)}.kpi.if{border-left:3px solid var(--info)}
table{width:100%;border-collapse:collapse;font-size:12.5px}
thead th{background:var(--surf3);color:var(--ink2);font-size:11px;font-weight:700;
padding:9px 12px;text-align:left;border-bottom:1px solid var(--line);white-space:nowrap}
tbody td{padding:10px 12px;border-bottom:1px solid var(--line2);vertical-align:middle}
tbody tr:last-child td{border-bottom:0}
tbody tr:hover{background:var(--surf2)}
tfoot td{padding:11px 12px;background:var(--surf3);font-weight:800;border-top:1px solid var(--line)}
td.num,th.num{text-align:right;font-variant-numeric:tabular-nums}
.tag{font-size:10px;font-weight:800;padding:3px 8px;border-radius:5px;white-space:nowrap;display:inline-block}
.tag.ok{background:var(--okbg);color:var(--ok)}
.tag.wn{background:var(--warnbg);color:var(--warn)}
.tag.dg{background:var(--dangerbg);color:var(--danger)}
.tag.if{background:var(--infobg);color:var(--info)}
.tag.gy{background:var(--dirtybg);color:var(--dirty)}
.al{border-radius:9px;padding:12px 14px;font-size:12px;line-height:1.65;display:flex;gap:9px}
.al.i{background:var(--infobg);border:1px solid var(--info);color:var(--info)}
.al.w{background:var(--warnbg);border:1px solid var(--warn);color:var(--warn)}
.al.g{background:var(--okbg);border:1px solid var(--ok);color:var(--ok)}
.al.d{background:var(--dangerbg);border:1px solid var(--danger);color:var(--danger)}
.al b{display:block;margin-bottom:2px}
.fl{font-size:10.5px;color:var(--muted);font-weight:700;margin:16px 0 8px}
.fl:first-child{margin-top:0}
.mini{font-size:11px;color:var(--muted);line-height:1.6}
.fld{margin-bottom:14px}
.fld .lb{font-size:11px;font-weight:700;color:var(--ink2);margin-bottom:5px;display:flex;gap:6px;align-items:center}
.fld .hp{font-size:10.5px;color:var(--muted);margin-top:4px;line-height:1.55}
.inp{width:100%;padding:9px 11px;border-radius:7px;border:1px solid var(--line);
background:var(--surf2);color:var(--ink);font-size:12.5px;font-family:inherit}
.inp:disabled{opacity:.55;cursor:not-allowed}
.sw3{width:44px;height:25px;border-radius:13px;background:var(--dirtybg);position:relative;
cursor:pointer;transition:.2s;flex-shrink:0}
.sw3:after{content:"";position:absolute;top:3px;left:3px;width:19px;height:19px;border-radius:50%;
background:#fff;transition:.2s;box-shadow:0 1px 2px rgba(0,0,0,.25)}
.sw3.on{background:var(--ok)}.sw3.on:after{left:22px}
.sw3.lk{opacity:.4;cursor:not-allowed}
.rowsw{display:flex;align-items:center;justify-content:space-between;gap:14px;
padding:13px 0;border-bottom:1px solid var(--line2)}
.rowsw:last-child{border-bottom:0}
.rowsw .tx2 .a{font-size:12.5px;font-weight:600;display:flex;align-items:center;gap:7px}
.rowsw .tx2 .b{font-size:10.5px;color:var(--muted);margin-top:2px;line-height:1.5}
.conf{background:var(--surf3);border-radius:7px;padding:3px;display:flex;gap:2px}
.conf .o{padding:5px 11px;border-radius:5px;font-size:11px;font-weight:700;color:var(--muted);cursor:pointer}
.conf .o.on{background:var(--surf);color:var(--ink);box-shadow:var(--sh)}
.tabs2{display:flex;gap:2px;border-bottom:1px solid var(--line);margin-bottom:16px}
.tabs2 .t{padding:9px 15px;font-size:12.5px;font-weight:700;color:var(--muted);cursor:pointer;
border-bottom:2px solid transparent}
.tabs2 .t.on{color:var(--brand);border-bottom-color:var(--brand)}
.dark .tabs2 .t.on{color:var(--ok);border-bottom-color:var(--ok)}
.lock{display:inline-flex;align-items:center;gap:4px;background:var(--dirtybg);color:var(--dirty);
padding:2px 7px;border-radius:5px;font-size:9.5px;font-weight:700}
.ovl{position:fixed;inset:0;background:rgba(8,14,11,.6);display:none;align-items:center;
justify-content:center;padding:30px;z-index:300;backdrop-filter:blur(2px)}
.ovl.on{display:flex}
.mdl{background:var(--surf);color:var(--ink);border-radius:13px;max-width:540px;width:100%;
max-height:86vh;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 24px 70px rgba(0,0,0,.5)}
.mdl .mh2{padding:15px 18px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:10px}
.mdl .mh2 h4{font-size:14.5px;font-weight:800}
.mdl .mh2 .x{margin-left:auto;cursor:pointer;color:var(--muted);font-size:19px;line-height:1}
.mdl .mb2{padding:18px;overflow-y:auto}
.mdl .mf{padding:14px 18px;border-top:1px solid var(--line);display:flex;gap:9px;justify-content:flex-end}
.notes{margin-top:24px;display:grid;grid-template-columns:repeat(auto-fit,minmax(330px,1fr));gap:14px}
.nc{background:#101714;border:1px solid #1D2822;border-radius:11px;padding:16px}
.nc h3{font-size:13px;color:#E7ECE8;margin-bottom:10px}
.nc p{font-size:12px;color:#A2B0A9;line-height:1.75;margin-bottom:8px}
.nc p:last-child{margin-bottom:0}
.nc b{color:var(--accent2)}
.nc code{background:#080D0B;padding:1px 6px;border-radius:3px;font-size:11px;color:var(--accent2)}
.nc ul{list-style:none;margin-top:7px}
.nc li{font-size:11.5px;color:#A2B0A9;padding:5px 0 5px 18px;position:relative;line-height:1.6}
.nc li:before{content:"\u25b8";position:absolute;left:1px;color:var(--accent)}
.nc table{margin-top:8px;font-size:11px}
.nc thead th{background:#16211D;color:#8A968F;border-bottom:1px solid #22302A;padding:7px 9px}
.nc tbody td{color:#A2B0A9;border-bottom:1px solid #1A2520;padding:7px 9px;background:transparent}
.rmk2{background:#2A1917;border-left:3px solid var(--danger);padding:10px 13px;font-size:11.5px;
color:#DFB4AD;margin-top:10px;line-height:1.65}
.hnt{background:#080D0B;border-left:3px solid var(--accent);padding:10px 13px;font-size:11.5px;
color:#96A39C;margin-top:10px;line-height:1.65}
.fx{color:#5BC192}.nx{color:#D98B80}

