document.getElementById('dm').onclick=function(){
const a=document.querySelector('.app');a.classList.toggle('dark');
this.textContent=a.classList.contains('dark')?'☀️ ライト':'🌙 ダーク'};
document.querySelectorAll('.sb a').forEach(a=>a.onclick=function(){
if(this.dataset.p===CUR)return;alert('画面 '+this.dataset.p+' へ遷移します')});
document.getElementById('prsw').onclick=()=>alert('施設の切り替え\n\n・サンプルホテル東京\n・サンプルホテル横浜');
document.querySelectorAll('.tabs2 .t').forEach(t=>t.onclick=function(){
this.parentNode.querySelectorAll('.t').forEach(x=>x.classList.remove('on'));this.classList.add('on')});
document.querySelectorAll('.sw3').forEach(s=>s.onclick=function(){
if(this.classList.contains('lk')){alert('この項目は運営管理者のみ変更できます');return}
this.classList.toggle('on')});
document.querySelectorAll('.conf').forEach(c=>c.querySelectorAll('.o').forEach(o=>o.onclick=function(){
c.querySelectorAll('.o').forEach(x=>x.classList.remove('on'));this.classList.add('on')}));
function openM(id){document.getElementById(id).classList.add('on')}
function closeM(id){document.getElementById(id).classList.remove('on')}
document.querySelectorAll('.ovl').forEach(o=>{o.onclick=e=>{if(e.target===o)o.classList.remove('on')};
const x=o.querySelector('.x');if(x)x.onclick=()=>o.classList.remove('on')});
